import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"35、【晉】 坤下離上","description":"周易尚氏學 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"周易尚氏學 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/shangshi/040.md","filePath":"classics/shangshi/040.md"}'),s={name:"classics/shangshi/040.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><p>離出地居五。南面響明而治。故曰晉。晉進也。四諸侯。康美也。大也。禮祭統。康周公注。康猶褒大也。易林隨之恆雲。實沉參虛。封為康侯。康侯略如大侯。為諸侯之美稱。猶詩之言齊侯。言平王也。坎為馬。坤亦為馬。坎為眾。坤亦為眾。故曰用錫馬蕃庶。艮為手故曰錫。錫予也。言康侯恭順。來賓於王。錫賁眾多。雜卦。晉晝也。艮為手。數三。離為晝。故曰晝日三接。侯果曰。大行人職曰。諸公三晌三問三勞。諸侯三響再問再勞。於男三晌一問一勞。即天子三接諸侯之禮也。晝日三接。即一晝三覿也。</p><p>彖曰。晉。進也。明出地上。順而麗乎大明。柔進而上行。是以康候用錫馬蕃庶。晝日三接也。</p><p>明出地上謂離。順謂坤。柔進而上行謂五。進居地上。得君位也。</p><p>象曰。明出地上。晉。君子以自昭明德。</p><p>明出地上。自然顯著德不求明而自明。故學易之君子。取法乎此。以自昭明德。言明德在已。自然昭朗。視能進與否耳。苟進而上行。未有不顯著者。昭正義雲。周氏等作</p><p>初六。晉如摧如。貞吉。同孚 裕無咎。</p><p>初陰。二三亦陰。得敵。故進而見摧。有應故貞吉。然初雖應四。以為二三所隔。應之甚難。故曰罔孚。裕緩也。言初與四終為正應。緩以俟之。則無咎也。與屯六二。十年乃字義同也。舊解皆不知得敵之理。虞翻以失位詁摧如。以罔罟詁罔孚。遂歧誤百出矣。</p><h3 id="象曰。晉如摧如。獨行正也。裕無咎。未受命也。" tabindex="-1">象曰。晉如摧如。獨行正也。裕無咎。未受命也。 <a class="header-anchor" href="#象曰。晉如摧如。獨行正也。裕無咎。未受命也。" aria-label="Permalink to “象曰。晉如摧如。獨行正也。裕無咎。未受命也。”">​</a></h3><p>初陰遇陰得敵。故曰獨行。有應故曰正未受命者。言初居勿用之位。尚未膺官守之命也。</p><p>六二。晉如愁如。貞吉。受茲介福於其王母。</p><p>二無應。進遇坎。坎為憂。故曰愁如。貞吉者。卜問吉也。介虞九家皆訓為大。坤為母。伏乾為大為福為王。故曰受茲介福於其王母。王母謂二。言二雖不宜於進。然得中為坤本位。必受此大福也。舊解謂王母指六五。六五亦陰。焉能福二。故夫陰遇陰陽遇陽。敵應之理不明。說易無不誤也。</p><h3 id="象曰。受茲介福。以中正也。" tabindex="-1">象曰。受茲介福。以中正也。 <a class="header-anchor" href="#象曰。受茲介福。以中正也。" aria-label="Permalink to “象曰。受茲介福。以中正也。”">​</a></h3><p>言二所以受茲大福者。以得此中正之位也。若六五則中而不正。各家因曰王母疑非五莫能當。豈知下坤方為母，伏乾故曰王母。易林此例甚多也。</p><p>六三。眾允悔亡。</p><p>施氏於升初六允升。讀作允（a：左上山左下卒）。就允（a）進也。此允字當與之同。故吳澄亦讀作眾允（a）。眾斯允（a）者眾進。坤為眾。言群陰並進而承陽也。故曰悔亡。虞翻詁允為信。朱子從之。與象傳上行之義不合。</p><h3 id="象曰。眾克之志。上行也。" tabindex="-1">象曰。眾克之志。上行也。 <a class="header-anchor" href="#象曰。眾克之志。上行也。" aria-label="Permalink to “象曰。眾克之志。上行也。”">​</a></h3><p>坎為志。上行謂進而承陽。即釋允（a）義。可見施讀合也。</p><p>九四。晉如鼠。貞厲。</p><p>釋文子夏傳作碩鼠。雲五技鼠也。古蓋音同通用。艮為鼠。為穴。坎為盜。鼠居穴中。伺隙盜竊。晝伏夜動。四失位。前臨夷主。下擁萬民。而坎為隱伏。為畏怯。欲進居五。恐下民生疑。欲下應初。又恐失五位。進退周章。有類於碩鼠。故貞厲也。</p><h3 id="象曰。碩鼠貞厲。位不當也。" tabindex="-1">象曰。碩鼠貞厲。位不當也。 <a class="header-anchor" href="#象曰。碩鼠貞厲。位不當也。" aria-label="Permalink to “象曰。碩鼠貞厲。位不當也。”">​</a></h3><p>位不當。即謂不中不正。</p><p>六五。悔亡。矢得勿恤。往吉。無不利。</p><p>六五得尊位。晌明而治。故侮亡。矢輔嗣作失。茲從孟馬荀虞鄭王肅諸家。坎為矢。五坎體。是得矢也。坎為恤。得矢為用。故勿恤。承陽故往吉。坎矢象。噬嗑九四雲得金矢。以坎為失也。易林常用。乃至漢末竟失傳。</p><h3 id="象曰。矢得勿恤。往有慶也。" tabindex="-1">象曰。矢得勿恤。往有慶也。 <a class="header-anchor" href="#象曰。矢得勿恤。往有慶也。" aria-label="Permalink to “象曰。矢得勿恤。往有慶也。”">​</a></h3><p>往遇陽。故曰往有慶。虞翻強命五變得乾為有慶。豈知六五上下皆乾陽。五居其中。往承陽故有慶。若五變為陽。往遇陽得敵。尚能有慶哉。</p><p>上九。晉其角。維用伐邑。厲吉。無咎。貞吝。</p><p>爻例上為角。故曰晉其角。坤為邑。離上九雲。王用出徵。有嘉折首。是離有徵伐象。蓋離為甲兵。故維用代色。然下應柔爻。故必振厲方吉元咎。以不全吉。故貞吝。</p><h3 id="象曰。維用伐邑。道未光也。" tabindex="-1">象曰。維用伐邑。道未光也。 <a class="header-anchor" href="#象曰。維用伐邑。道未光也。" aria-label="Permalink to “象曰。維用伐邑。道未光也。”">​</a></h3><p>離為光明。至上光將熄矣。夫王道大光。則無用征伐。用征伐必未光也。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
